(()=>{const KEY="jh-ai-edge-submission",MAX_AGE_MS=10*60*1000;function currentPlacement(){const q=new URLSearchParams(location.search);return(q.get("source")||q.get("placement")||"newsletter:direct").trim().slice(0,100)}function trackSuccess(){let prior=null;try{prior=JSON.parse(sessionStorage.getItem(KEY)||"null")}catch{}const fresh=prior&&Number.isFinite(prior.timestamp)&&Date.now()-prior.timestamp>=0&&Date.now()-prior.timestamp<MAX_AGE_MS;if(!fresh){const placement=prior?.placement||currentPlacement();window.JHAnalytics?.track("newsletter_submit",{placement});window.JHAnalytics?.track("newsletter_success",{placement});try{sessionStorage.setItem(KEY,JSON.stringify({timestamp:Date.now(),placement}))}catch{}}}function init(){if(window.top!==window.self){try{window.top.location.replace(window.location.href);return}catch{}}trackSuccess()}window.addEventListener("load",init,{once:true})})();
